-- FlashFusion target Supabase schema. Provenance: [INFERRED]. Review before production.
create extension if not exists pgcrypto;
create table if not exists tenants (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, segment text default 'unknown', created_at timestamptz default now());
create table if not exists profiles (id uuid primary key, tenant_id uuid references tenants(id), display_name text, email text, created_at timestamptz default now());
create table if not exists roles (key text primary key, name text not null, description text not null);
create table if not exists memberships (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), user_id uuid not null, role_key text references roles(key), status text default 'active');
create table if not exists assessment_templates (id uuid primary key default gen_random_uuid(), key text unique not null, name text not null, version int default 1, assessment_type text not null, is_active boolean default true);
create table if not exists assessment_questions (id uuid primary key default gen_random_uuid(), template_id uuid references assessment_templates(id), section_key text, question_text text not null, response_type text not null, weight numeric default 1, sort_order int default 0);
create table if not exists assessments (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), template_id uuid references assessment_templates(id), user_id uuid, assessment_type text not null, status text default 'draft', score numeric, maturity_band text, recommendation_summary text, submitted_at timestamptz, created_at timestamptz default now());
create table if not exists assessment_answers (id uuid primary key default gen_random_uuid(), assessment_id uuid references assessments(id) on delete cascade, question_id uuid references assessment_questions(id), answer jsonb not null, score numeric, unique(assessment_id, question_id));
create table if not exists assessment_reports (id uuid primary key default gen_random_uuid(), assessment_id uuid references assessments(id), tenant_id uuid references tenants(id), report_markdown text not null, report_status text default 'draft', approved_by uuid, approved_at timestamptz);
create table if not exists clients (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), company_name text not null, status text default 'lead');
create table if not exists engagements (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), client_id uuid references clients(id), package_key text not null, status text default 'proposed', start_date date, end_date date, success_benchmark text);
create table if not exists roadmaps (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), engagement_id uuid references engagements(id), title text not null, status text default 'draft');
create table if not exists roadmap_items (id uuid primary key default gen_random_uuid(), roadmap_id uuid references roadmaps(id), title text not null, status text default 'not_started', priority text default 'medium', proof_required text);
create table if not exists client_messages (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), engagement_id uuid references engagements(id), sender_id uuid, body text not null, created_at timestamptz default now());
create table if not exists products (id uuid primary key default gen_random_uuid(), key text unique not null, name text not null, description text not null, product_type text not null, status text default 'draft');
create table if not exists purchases (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), user_id uuid, product_id uuid references products(id), stripe_checkout_session_id text unique, status text default 'pending', amount_cents int, currency text default 'usd');
create table if not exists agents (id uuid primary key default gen_random_uuid(), key text unique not null, name text not null, description text not null, risk_level text default 'medium');
create table if not exists agent_runs (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), agent_id uuid references agents(id), user_id uuid, task_type text not null, input_summary text not null, output_summary text, status text default 'queued', requires_approval boolean default false);
create table if not exists model_invocations (id uuid primary key default gen_random_uuid(), agent_run_id uuid references agent_runs(id), provider text not null, model text not null, prompt_hash text not null, estimated_cost_usd numeric);
create table if not exists tool_invocations (id uuid primary key default gen_random_uuid(), agent_run_id uuid references agent_runs(id), tool_name text not null, permission_key text not null, status text default 'started');
create table if not exists eval_results (id uuid primary key default gen_random_uuid(), agent_run_id uuid references agent_runs(id), rubric_key text not null, score numeric not null, passed boolean default false, findings jsonb default '{}'::jsonb);
create table if not exists human_approvals (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), subject_type text not null, subject_id uuid not null, requested_by uuid, approved_by uuid, status text default 'pending', reason text, resolved_at timestamptz);
create table if not exists incidents (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), severity text not null, title text not null, summary text not null, status text default 'open');
create table if not exists analytics_events (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), user_id uuid, event_name text not null, properties jsonb default '{}'::jsonb, occurred_at timestamptz default now());
create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), tenant_id uuid references tenants(id), actor_id uuid, action text not null, subject_type text not null, subject_id uuid, metadata jsonb default '{}'::jsonb, created_at timestamptz default now());
alter table tenants enable row level security; alter table profiles enable row level security; alter table memberships enable row level security; alter table assessments enable row level security; alter table assessment_answers enable row level security; alter table assessment_reports enable row level security; alter table clients enable row level security; alter table engagements enable row level security; alter table roadmaps enable row level security; alter table roadmap_items enable row level security; alter table client_messages enable row level security; alter table purchases enable row level security; alter table agents enable row level security; alter table agent_runs enable row level security; alter table model_invocations enable row level security; alter table tool_invocations enable row level security; alter table eval_results enable row level security; alter table human_approvals enable row level security; alter table incidents enable row level security; alter table analytics_events enable row level security; alter table audit_logs enable row level security;
